'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/fast/max' );

var normalize = require( './normalize.js' );

/**
* Method to draw the bar.
*
* @private
* @name initialize
* @returns {void}
*/
function initialize() {
	var bckColorArr;
	var frdColorArr;
	var glyphArr;
	var obj;

	// x axis label space
	var x = 0;

	// y axis label space
	var y = 0;

	// z axis label space
	var z = 0;

	// w axis label space
	var w = 0;
	var i;
	var j;

	x = 0;
	z = 0;
	this._plotArea = {};
	if ( this._axisDataObj ) {
		// X axis
		if ( this._axisDataObj[ 0 ].axis ) {
			obj = normalize( this._axisDataObj[ 0 ].data, this._axisDataObj[ 0 ].labelFormate, 'graphemes' );
			x = obj.max;
			this._axisDataObj[ 0 ].data = obj.data;
		}

		// Y axis
		if ( this._axisDataObj[ 1 ].axis ) {
			obj = normalize( this._axisDataObj[ 1 ].data, this._axisDataObj[ 1 ].labelFormate, 'graphemes' );
			y = 1;
			this._axisDataObj[ 1 ].data = obj.data;
		}

		// Z Axis
		if ( this._axisDataObj[ 2 ].axis ) {
			obj = normalize( this._axisDataObj[ 2 ].data, this._axisDataObj[ 2 ].labelFormate, 'graphemes' );
			z = obj.max;
			this._axisDataObj[ 2 ].data = obj.data;
		}

		// W axis
		if ( this._axisDataObj[ 3 ].axis ) {
			obj = normalize( this._axisDataObj[ 3 ].data, this._axisDataObj[ 3 ].labelFormate, 'graphemes' );
			w = 1;
			this._axisDataObj[ 3 ].data = obj.data;
		}
	}

	// Setting plot area
	this._plotArea.x = x;
	this._plotArea.y = y;
	this._plotArea.z = this._plotAreaWidth + x + 1;
	this._plotArea.w = this._plotAreaHeight + y + 1;

	// Setting height and width for the matrix array

	// Axis tics space + plotAreaHeight
	this._height = y + w + 2 + this._plotAreaHeight;
	this._width = x + z + 2 + this._plotAreaWidth;
	this._glyphMatrix = [];
	this._backgroundColorMatrix = [];
	this._foregroundColorMatrix = [];
	for ( i = 0; i < this._height; i++ ) {
		bckColorArr = new Array( this._width );
		frdColorArr = new Array( this._width );
		glyphArr = new Array( this._width );
		for ( j = 0; j < this._width; j++ ) {
			glyphArr[ j ] = this._glyph;
			bckColorArr[ j ] = this._backgroundColor;
			frdColorArr[ j ] = this.foregroundColor;
		}
		this._glyphMatrix.push( glyphArr );
		this._backgroundColorMatrix.push( bckColorArr );
		this._foregroundColorMatrix.push( frdColorArr );
	}
}

module.exports = initialize;
